from collections import deque


def minCoinsWithChange(coins, amount):
    if amount == 0:
        return 0
    coins = sorted(set(coins))
    big = coins[-1]
    lo, hi = -big, amount + big
    dist = [-1] * (hi - lo + 1)
    dist[0 - lo] = 0
    queue = deque([0])
    while queue:
        x = queue.popleft()
        d = dist[x - lo]
        for c in coins:
            for y in (x + c, x - c):
                if lo <= y <= hi and dist[y - lo] < 0:
                    if y == amount:
                        return d + 1
                    dist[y - lo] = d + 1
                    queue.append(y)
    return -1
